## Implementation
Create `apps/web/hooks/useConnection.ts`:
- Provides: status, syncState, reconnect, isConnected, isReconnecting
- Cleanup connection on unmount or roomId change

## Code from Plan
```typescript
export function useConnection() {
  const status = useAtomValue(connectionStatusAtom);
  const syncState = useAtomValue(syncStateAtom);
  const roomIdOption = useAtomValue(roomIdAtom);
  const roomId = Option.getOrNull(roomIdOption);
  const reconnect = useAtomSet(reconnectFn);

  useEffect(() => {
    return () => {
      if (roomId) clearRoomConnection(roomId);
    };
  }, [roomId]);

  return {
    status,
    syncState,
    reconnect: () => roomId && reconnect({ roomId }),
    isConnected: status === "connected",
    isReconnecting: status === "reconnecting"
  };
}
```

