## AsyncButton Pattern
```typescript
function AsyncButton({ result, onClick, children, ...props }) {
  const isLoading = Result.isWaiting(result);
  return (
    <Button disabled={isLoading} onClick={onClick} {...props}>
      {isLoading ? <Spinner /> : children}
    </Button>
  );
}
```

## StatusBadge Pattern
```typescript
function StatusBadge({ status }: { status: ConnectionStatus }) {
  const variant = Match.value(status).pipe(
    Match.when("connected", () => "success"),
    Match.when("reconnecting", () => "warning"),
    Match.orElse(() => "secondary")
  );
  return <Badge variant={variant}>{status}</Badge>;
}
```

